#[derive(ValidateStream, ParseStream)]
struct FuStructDfuCsrFile {
    file_id: [char; 8] == "CSR-dfu2",
    file_version: u16le == 0x02,
    file_len: u32le,
    file_hdr_len: u16le,
    //file_desc: [char; 64], -- useless
}

#[repr(u8)]
enum FuDfuCsrReportId {
    Command = 0x01,
    Status = 0x02,
    Control = 0x03,
}

#[repr(u8)]
enum FuDfuCsrCommand {
    Upgrade = 0x01,
}

#[derive(New)]
struct FuStructDfuCsrCommandHeader {
    report_id: FuDfuCsrReportId,
    command: FuDfuCsrCommand,
    idx: u16le,
    chunk_sz: u16le,
}
--- build files ---
if gusb.found()
cargs = ['-DG_LOG_DOMAIN="FuPluginDfuCsr"']
plugins += {meson.current_source_dir().split('/')[-1]: true}

plugin_quirks += files('dfu-csr.quirk')
plugin_builtins += static_library('fu_plugin_dfu_csr',
  rustgen.process('fu-dfu-csr.rs'),
  sources: [
    dfu_rs[1], # header
    'fu-dfu-csr-device.c',
    'fu-dfu-csr-firmware.c',
    'fu-dfu-csr-plugin.c',
  ],
  include_directories: [
    root_incdir,
    fwupd_incdir,
    fwupdplugin_incdir,
    plugindfu_incdir,
  ],
  c_args: cargs,
  dependencies: plugin_deps,
  link_with: [
    fwupdplugin,
    plugin_builtin_dfu,
  ],
)
endif
